previewCss:
.darma-loader-darma-b12-book-flip-pages { --accent: var(--loader-color, #7c3aed); --accent-2: var(--loader-secondary-color, #c084fc); width: var(--loader-size, 108px); height: calc(var(--loader-size, 108px) * .68); position: relative; perspective: 520px; }
.darma-loader-darma-b12-book-flip-pages::before, .darma-loader-darma-b12-book-flip-pages::after { content: ''; position: absolute; top: 0; width: 50%; height: 100%; background: linear-gradient(var(--accent), var(--accent-2)); }
.darma-loader-darma-b12-book-flip-pages::before { left: 0; border-radius: 6px 0 0 6px; }
.darma-loader-darma-b12-book-flip-pages::after { right: 0; border-radius: 0 6px 6px 0; filter: brightness(.88); }
.darma-loader-darma-b12-book-flip-pages span { position: absolute; z-index: 2; top: 5%; left: 50%; width: 47%; height: 90%; transform-origin: left center; border-radius: 0 5px 5px 0; background: linear-gradient(90deg, #e2e8f0, #f8fafc 22%); box-shadow: 0 2px 8px rgba(15, 23, 42, .22); animation: darma-loader-darma-b12-book-flip-pages-turn calc(var(--loader-speed, 1s) * 1.8) ease-in-out infinite; }
.darma-loader-darma-b12-book-flip-pages span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * -.6); }
.darma-loader-darma-b12-book-flip-pages span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * -1.2); }
@keyframes darma-loader-darma-b12-book-flip-pages-turn { 0% { transform: rotateY(0deg); } 100% { transform: rotateY(-180deg); } }

